23	// Release-asset download. The one irreducibly forge-specific piece of the
24	// plugin system is where release binaries live; it's contained here as a
25	// small per-host URL convention table with a declarative escape hatch
26	// (download_url in entire-plugin.yml). Everything else — version listing,
27	// metadata, the index — runs on the git protocol.
28	
29	// errAssetNotFound distinguishes "this tag has no matching asset" (worth
30	// trying the next-highest tag — a pushed tag whose release isn't published
31	// yet) from transport errors (not worth retrying on another tag).
32	var errAssetNotFound = errors.New("no matching release asset")
33	
34	// pluginHTTPClient bounds the total time for a single asset download.
35	// Plugins can be tens of MB; 5 minutes is generous even on slow links.
36	var pluginHTTPClient = &http.Client{Timeout: 5 * time.Minute}
37	
38	// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
39	// of MB; the cap exists so a misconfigured URL serving an endless stream
40	// can't fill the disk.
41	const maxPluginAssetSize = 512 << 20 // 512 MiB
42	
43	// releaseAssetBaseURL returns the URL prefix release assets live under for
44	// the repo's host. GitHub and the Gitea family share a convention; GitLab
45	// has its own. Unknown hosts default to the GitHub-style convention (most
46	// self-hosted forges mirror it) — authors on hosts that don't can declare
47	// download_url in entire-plugin.yml.
48	func releaseAssetBaseURL(repoURL, tag string) (string, error) {
49		u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
50		if err != nil {
51			return "", fmt.Errorf("parse repo URL: %w", err)
52		}
53		if u.Scheme != "https" && u.Scheme != "http" {
54			return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", repoURL, pluginMetadataFileName)
55		}
56		base := strings.TrimSuffix(u.String(), "/")
57		host := strings.ToLower(u.Hostname())
58		if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
59			return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
60		}
61		return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
62	}
63	
64	// expandDownloadTemplate expands the author-declared download_url template.
65	// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
66	func expandDownloadTemplate(tmpl, name, tag, asset string) string {
67		r := strings.NewReplacer(
68			"{name}", name,
69			"{tag}", tag,
70			"{version}", strings.TrimPrefix(tag, "v"),
71			"{os}", runtime.GOOS,
72			"{arch}", runtime.GOARCH,
73			"{asset}", asset,
74		)
75		return r.Replace(tmpl)
76	}
77	
78	// archAliases maps a GOARCH to the spellings seen in release asset names.
79	func archAliases(goarch string) []string {
80		switch goarch {
81		case "amd64":
82			return []string{"amd64", "x86_64"}
83		case "arm64":
84			return []string{"arm64", "aarch64"}
85		default:
86			return []string{goarch}
87		}
88	}
89	
90	// osAliases maps a GOOS to asset-name spellings, most specific first.
91	// "all" covers macOS universal binaries.
92	func osAliases(goos string) []string {
93		if goos == darwinGOOS {
94			return []string{"darwin", "macos", "all"}
95		}
96		return []string{goos}
97	}
98	
99	// assetCandidates returns release asset filenames to try for this platform,
100	// in preference order: archives before raw binaries, version-in-name
101	// (goreleaser's default template) before version-less.
102	func assetCandidates(name, tag string) []string {
103		binName := pluginBinaryPrefix + name
104		version := strings.TrimPrefix(tag, "v")
105		stems := make([]string, 0, 16)
106		for _, osName := range osAliases(runtime.GOOS) {
107			for _, arch := range archAliases(runtime.GOARCH) {
108				stems = append(stems,
109					fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
110					fmt.Sprintf("%s_%s_%s", binName, osName, arch),
111				)
112			}
113		}
114		exts := []string{".tar.gz", ".zip", ""}
115		if runtime.GOOS == windowsGOOS {
116			exts = []string{".zip", ".tar.gz", ".exe"}
117		}
118		var out []string
119		for _, ext := range exts {
120			for _, stem := range stems {
121				out = append(out, stem+ext)
122			}
123		}
124		return out
125	}
126	
127	// checksumCandidates returns filenames the checksum manifest may go by.
128	func checksumCandidates(name, tag string) []string {
129		binName := pluginBinaryPrefix + name
130		version := strings.TrimPrefix(tag, "v")
131		return []string{
132			"checksums.txt",
133			fmt.Sprintf("%s_%s_checksums.txt", binName, version),
134			binName + "_checksums.txt",
135		}
136	}
137	
138	// parseChecksums parses "hex  filename" lines (sha256sum format) into a
139	// filename → digest map.
140	func parseChecksums(data []byte) map[string]string {
141		out := make(map[string]string)
142		for _, line := range strings.Split(string(data), "\n") {
143			fields := strings.Fields(line)
144			if len(fields) != 2 {
145				continue
146			}
147			// sha256sum marks binary-mode files with a leading *.
148			out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
149		}
150		return out
151	}
152	
153	// selectAssetFromChecksums picks the preferred candidate present in the
154	// checksum manifest. The manifest lists what was actually published, so
155	// this avoids probing candidate URLs one by one.
156	func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
157		for _, c := range assetCandidates(name, tag) {
158			if d, present := sums[c]; present {
159				return c, d, true
160			}
161		}
162		return "", "", false
163	}
164	
165	// fetchedAsset is the result of downloadPluginAsset: a verified asset on
166	// disk in a caller-owned staging dir.
167	type fetchedAsset struct {
168		// Path is the downloaded asset file inside the staging dir.
169		Path string
170		// Asset is the asset filename that matched.
171		Asset string
172		// SHA256 is the hex digest of the downloaded bytes.
173		SHA256 string
174	}
175	
176	// downloadPluginAsset locates and downloads the release asset for name@tag
177	// into stagingDir, verifying against the release's checksum manifest when
178	// one is published. Returns errAssetNotFound (possibly wrapped) when the
179	// tag has no asset for this platform.
180	func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string) (*fetchedAsset, error) {
181		assetURL := func(asset string) (string, error) {
182			if meta != nil && meta.DownloadURL != "" {
183				return expandDownloadTemplate(meta.DownloadURL, name, tag, asset), nil
184			}
185			base, err := releaseAssetBaseURL(repoURL, tag)
186			if err != nil {
187				return "", err
188			}
189			return base + asset, nil
190		}
191	
192		// A download_url template without {asset} is a single fully-specified
193		// URL; there is nothing to select.
194		if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
195			u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
196			return fetchAndVerify(ctx, u, path.Base(u), "", stagingDir)
197		}
198	
199		// Preferred path: fetch the checksum manifest and pick from what was
200		// actually published.
201		for _, cs := range checksumCandidates(name, tag) {
202			u, err := assetURL(cs)
203			if err != nil {
204				return nil, err
205			}
206			data, err := httpGetSmall(ctx, u)
207			if err != nil {
208				continue
209			}
210			asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
211			if !ok {
212				// This manifest lists nothing for the platform. Keep going: a
213				// stale or hand-written root checksums.txt must not mask a
214				// goreleaser manifest under another candidate name, or a
215				// published asset still reachable by the probe fallback.
216				// Falling through doesn't weaken verification — an attacker
217				// who controls the manifest could list a malicious digest
218				// directly.
219				continue
220			}
221			au, err := assetURL(asset)
222			if err != nil {
223				return nil, err
224			}
225			return fetchAndVerify(ctx, au, asset, digest, stagingDir)
226		}
227	
228		// Fallback: probe candidates directly (release without a checksum
229		// manifest). No digest to verify against; the manifest records the
230		// digest we computed so upgrades can at least detect drift.
231		for _, asset := range assetCandidates(name, tag) {
232			u, err := assetURL(asset)
233			if err != nil {
234				return nil, err
235			}
236			fa, err := fetchAndVerify(ctx, u, asset, "", stagingDir)
237			if err == nil {
238				return fa, nil
239			}
240			if !errors.Is(err, errAssetNotFound) {
241				return nil, err
242			}
243		}
244		return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, repoURL, tag)
245	}
246	
247	// httpGetSmall fetches a small text resource (checksum manifests).
248	func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
249		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
250		if err != nil {
251			return nil, fmt.Errorf("build request for %s: %w", rawURL, err)
252		}
253		resp, err := pluginHTTPClient.Do(req)
254		if err != nil {
255			return nil, fmt.Errorf("GET %s: %w", rawURL, err)
256		}
257		defer resp.Body.Close()
258		if resp.StatusCode != http.StatusOK {
259			return nil, fmt.Errorf("GET %s: %s", rawURL, resp.Status)
260		}
261		data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
262		if err != nil {
263			return nil, fmt.Errorf("read %s: %w", rawURL, err)
264		}
265		return data, nil
266	}
267	
268	// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
269	// it writes. A non-empty wantDigest is enforced; an empty one records the
270	// computed digest. 404/410 map to errAssetNotFound. Partial files are
271	// removed on verification failure so a hostile or truncated download never
272	// lingers in staging.
273	func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
274		// The asset name is normally one of our own candidates, but the
275		// single-URL download_url template path derives it from the URL and a
276		// future caller could pass a name straight from a remote manifest.
277		// Refuse anything that wouldn't stay inside stagingDir. Backslash is
278		// rejected on every platform — it's a separator on Windows, and a
279		// literal backslash in an asset name is never legitimate.
280		if asset == "" || asset == "." || asset == ".." ||
281			strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
282			return nil, fmt.Errorf("unsafe release asset name %q", asset)
283		}
284		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
285		if err != nil {
286			return nil, fmt.Errorf("build request for %s: %w", rawURL, err)
287		}
288		resp, err := pluginHTTPClient.Do(req)
289		if err != nil {
290			return nil, fmt.Errorf("download %s: %w", rawURL, err)
291		}
292		defer resp.Body.Close()
293		switch resp.StatusCode {
294		case http.StatusOK:
295		case http.StatusNotFound, http.StatusGone:
296			return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, rawURL, resp.Status)
297		default:
298			return nil, fmt.Errorf("download %s: %s", rawURL, resp.Status)
299		}
300	
301		dest := filepath.Join(stagingDir, asset)
302		out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
303		if err != nil {
304			return nil, fmt.Errorf("create staging file: %w", err)
305		}
306		h := sha256.New()
307		n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
308		closeErr := out.Close()
309		if err != nil {
310			_ = os.Remove(dest)
311			return nil, fmt.Errorf("download %s: %w", rawURL, err)
312		}
313		if closeErr != nil {
314			_ = os.Remove(dest)
315			return nil, fmt.Errorf("write staging file: %w", closeErr)
316		}
317		if n > maxPluginAssetSize {
318			_ = os.Remove(dest)
319			return nil, fmt.Errorf("download %s: exceeds %d byte limit", rawURL, int64(maxPluginAssetSize))
320		}
321		got := hex.EncodeToString(h.Sum(nil))
322		if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
323			_ = os.Remove(dest)
324			return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
325		}
326		return &fetchedAsset{Path: dest, Asset: asset, SHA256: got}, nil
327	}
328	
329	// extractPluginBinary locates the plugin executable inside the downloaded
330	// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
331	// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
332	// basename matches entire-<name>[.exe], wherever it sits in the archive.
333	func extractPluginBinary(assetPath, name, destPath string) error {
334		binName := pluginBinaryPrefix + name
335		lower := strings.ToLower(assetPath)
336		switch {
337		case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
338			return extractFromTarGz(assetPath, binName, destPath)
339		case strings.HasSuffix(lower, ".zip"):
340			return extractFromZip(assetPath, binName, destPath)
341		default:
342			src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
343			if err != nil {
344				return fmt.Errorf("open asset: %w", err)
345			}
346			defer src.Close()
347			return writeExecutable(src, destPath)
348		}
349	}
350	
351	// matchesPluginBinary reports whether an archive entry basename is the
352	// plugin binary, tolerating a Windows extension.
353	func matchesPluginBinary(entryName, binName string) bool {
354		base := path.Base(filepath.ToSlash(entryName))
355		if base == binName {
356			return true
357		}
358		return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+".exe")
359	}
360	
361	// safeArchiveEntry rejects entry names that could escape an extraction
362	// root. We only ever extract a single matched file to a fixed dest, so this
363	// is defense in depth against a hostile archive masking as a plugin.
364	func safeArchiveEntry(entryName string) bool {
365		clean := path.Clean(filepath.ToSlash(entryName))
366		return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
367	}
368	
369	func extractFromTarGz(archivePath, binName, destPath string) error {
370		f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
371		if err != nil {
372			return fmt.Errorf("open archive: %w", err)
373		}
374		defer f.Close()
375		gz, err := gzip.NewReader(f)
376		if err != nil {
377			return fmt.Errorf("open gzip: %w", err)
378		}
379		defer gz.Close()
380		tr := tar.NewReader(gz)
381		for {
382			hdr, err := tr.Next()
383			if errors.Is(err, io.EOF) {
384				break
385			}
386			if err != nil {
387				return fmt.Errorf("read tar: %w", err)
388			}
389			if hdr.Typeflag != tar.TypeReg || !safeArchiveEntry(hdr.Name) || !matchesPluginBinary(hdr.Name, binName) {
390				continue
391			}
392			return writeExecutable(io.LimitReader(tr, maxPluginAssetSize), destPath)
393		}
394		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
395	}
396	
397	func extractFromZip(archivePath, binName, destPath string) error {
398		zr, err := zip.OpenReader(archivePath)
399		if err != nil {
400			return fmt.Errorf("open zip: %w", err)
401		}
402		defer zr.Close()
403		for _, f := range zr.File {
404			if f.FileInfo().IsDir() || !safeArchiveEntry(f.Name) || !matchesPluginBinary(f.Name, binName) {
405				continue
406			}
407			rc, err := f.Open()
408			if err != nil {
409				return fmt.Errorf("open zip entry: %w", err)
410			}
411			defer rc.Close()
412			return writeExecutable(io.LimitReader(rc, maxPluginAssetSize), destPath)
413		}
414		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
415	}
416	
417	// writeExecutable writes r to destPath with the executable bit set.
418	// Explicit chmod (not inherited archive mode) because zip-built and
419	// raw-binary releases routinely lose the bit — the #1 "downloaded plugin
420	// doesn't run" failure.
421	func writeExecutable(r io.Reader, destPath string) error {
422		out, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o755) //nolint:gosec // dest is inside the managed pkg tree; the binary must be executable
423		if err != nil {
424			return fmt.Errorf("create binary: %w", err)
425		}
426		if _, err := io.Copy(out, r); err != nil {
427			_ = out.Close()
428			_ = os.Remove(destPath)
429			return fmt.Errorf("write binary: %w", err)
430		}
431		if err := out.Close(); err != nil {
432			_ = os.Remove(destPath)
433			return fmt.Errorf("close binary: %w", err)
434		}
435		return nil
436	}
