1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"os/exec"
9		"sort"
10		"strings"
11	
12		"golang.org/x/mod/semver"
13	)
14	
15	// Host-agnostic remote inspection over the git protocol. Version listing
16	// uses `git ls-remote --tags`, which behaves identically on GitHub, GitLab,
17	// Gitea/Forgejo, and any self-hosted server, inherits the user's existing
18	// git auth (SSH agent, credential helpers), and needs no forge REST client.
19	// The shell-out (vs go-git) is deliberate: this path needs the user's
20	// credential helpers and proxy config, the same reason hooks.go shells out
21	// for network-touching operations.
22	
23	// gitQuiet returns an exec.Cmd for git with terminal prompts disabled, so
24	// an auth-requiring remote fails fast instead of hanging a non-interactive
25	// run on a username prompt.
26	func gitQuiet(ctx context.Context, args ...string) *exec.Cmd {
27		cmd := exec.CommandContext(ctx, "git", args...)
28		cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
29		return cmd
30	}
31	
32	// listRemoteSemverTags returns the repo's semver tags ("v"-prefixed or
33	// bare), sorted descending by semantic version. Non-semver tags are
34	// ignored.
35	func listRemoteSemverTags(ctx context.Context, repoURL string) ([]string, error) {
36		// --refs suppresses peeled ^{} entries for annotated tags.
37		out, err := gitQuiet(ctx, "ls-remote", "--tags", "--refs", repoURL).Output()
38		if err != nil {
39			return nil, fmt.Errorf("list tags of %s: %w%s", repoURL, err, stderrSuffix(err))
40		}
41		var tags []string
42		for _, line := range strings.Split(string(out), "\n") {
43			fields := strings.Fields(line)
44			if len(fields) != 2 {
45				continue
46			}
47			tag := strings.TrimPrefix(fields[1], "refs/tags/")
48			if semver.IsValid(canonicalSemver(tag)) {
49				tags = append(tags, tag)
50			}
51		}
52		sort.Slice(tags, func(i, j int) bool {
53			return semver.Compare(canonicalSemver(tags[i]), canonicalSemver(tags[j])) > 0
54		})
55		return tags, nil
56	}
57	
58	// canonicalSemver maps a tag to the "v"-prefixed form x/mod/semver expects.
59	func canonicalSemver(tag string) string {
60		if strings.HasPrefix(tag, "v") {
61			return tag
62		}
63		return "v" + tag
64	}
65	
66	// stderrSuffix extracts captured stderr from an exec.ExitError for error
67	// messages; git's stderr is where the actionable detail lives. Only
68	// populated when the command was started via Output().
69	func stderrSuffix(err error) string {
70		var exitErr *exec.ExitError
71		if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
72			return ": " + strings.TrimSpace(string(exitErr.Stderr))
73		}
74		return ""
75	}
76	
77	// fetchPluginMetadataAtTag reads entire-plugin.yml at the given tag without
78	// a user-visible clone: a blobless shallow clone into a discarded temp dir,
79	// falling back to a plain shallow clone for servers that don't allow
80	// partial-clone filters (uploadpack.allowFilter defaults to off outside the
81	// big forges). Returns (nil, nil) when the repo has no metadata file —
82	// metadata is optional by design.
83	func fetchPluginMetadataAtTag(ctx context.Context, repoURL, tag string) (*PluginMetadata, error) {
84		tmp, err := os.MkdirTemp("", "entire-plugin-meta-")
85		if err != nil {
86			return nil, fmt.Errorf("create temp dir: %w", err)
87		}
88		defer os.RemoveAll(tmp)
89	
90		cloneArgs := func(filter bool) []string {
91			args := []string{"clone", "--depth", "1", "--no-checkout", "--branch", tag, "--quiet"}
92			if filter {
93				args = append(args, "--filter=blob:none")
94			}
95			return append(args, repoURL, tmp)
96		}
97		// Output() (not Run()) so stderr is captured into the ExitError for
98		// error messages; clone --quiet writes nothing to stdout.
99		if _, err := gitQuiet(ctx, cloneArgs(true)...).Output(); err != nil {
100			// Retry without the filter; the clone dir may be half-created.
101			if rmErr := os.RemoveAll(tmp); rmErr != nil {
102				return nil, fmt.Errorf("clean temp clone dir: %w", rmErr)
103			}
104			if _, err := gitQuiet(ctx, cloneArgs(false)...).Output(); err != nil {
105				return nil, fmt.Errorf("clone %s at %s: %w%s", repoURL, tag, err, stderrSuffix(err))
106			}
107		}
108		// `git show <rev>:<path>` peels annotated tags and, in a blobless
109		// clone, lazily fetches just this one blob from the promisor remote.
110		out, err := gitQuiet(ctx, "-C", tmp, "show", tag+":"+pluginMetadataFileName).Output()
111		if err != nil {
112			// Missing file and missing tag both surface as exit 128; only the
113			// missing-file case is benign. Disambiguate via stderr.
114			if strings.Contains(stderrSuffix(err), "does not exist") ||
115				strings.Contains(stderrSuffix(err), "exists on disk, but not in") {
116				return nil, nil //nolint:nilnil // metadata is optional
117			}
118			return nil, fmt.Errorf("read %s at %s: %w%s", pluginMetadataFileName, tag, err, stderrSuffix(err))
119		}
120		return ParsePluginMetadata(out)
121	}
122	
123	// pluginNameFromRepoURL derives the bare plugin name from a repository URL
124	// basename: .../entire-run(.git) → "run". Used when entire-plugin.yml is
125	// absent or doesn't declare a name.
126	func pluginNameFromRepoURL(repoURL string) (string, error) {
127		trimmed := strings.TrimSuffix(strings.TrimSuffix(repoURL, "/"), ".git")
128		base := trimmed
129		if i := strings.LastIndexAny(trimmed, "/:"); i >= 0 {
130			base = trimmed[i+1:]
131		}
132		if !strings.HasPrefix(base, pluginBinaryPrefix) {
133			return "", fmt.Errorf("repository basename %q does not start with %q; declare a name in %s", base, pluginBinaryPrefix, pluginMetadataFileName)
134		}
135		name := strings.TrimPrefix(base, pluginBinaryPrefix)
136		if err := validatePluginName(name); err != nil {
137			return "", err
138		}
139		return name, nil
140	}
