17	
18	// Remote install orchestration: resolve tag → fetch metadata → download +
19	// verify + extract → place under pkg/<name>/ → link into bin/ → write
20	// manifest. The bin/ link goes through the same InstallPluginFromPath used
21	// by local-dev installs, so conflict handling, atomic replace, and the
22	// Windows symlink fallbacks are shared, not duplicated.
23	
24	// maxTagFallbacks bounds how many tags we walk down when the newest tag has
25	// no published assets (tag pushed, release not finished).
26	const maxTagFallbacks = 3
27	
28	// RemoteInstallOptions configures InstallPluginFromRepo.
29	type RemoteInstallOptions struct {
30		// RepoURL is the full git URL of the plugin repository.
31		RepoURL string
32		// Pin, when non-empty, installs exactly this tag and marks the
33		// manifest pinned so upgrade skips it.
34		Pin string
35		// Force replaces an existing managed entry with the same name.
36		Force bool
37	}
38	
39	// RemoteInstallResult is what a successful remote install produced.
40	type RemoteInstallResult struct {
41		Installed *InstalledPlugin
42		Manifest  *PluginManifest
43		Metadata  *PluginMetadata
44		// SkippedTags lists newer tags that were passed over for missing
45		// assets, newest first. Callers surface these as warnings.
46		SkippedTags []string
47	}
48	
49	// InstallPluginFromRepo installs a plugin from a git repository URL.
50	// Dependency resolution deliberately does not happen here — callers
51	// (the install command) plan and confirm dependency installs first.
52	func InstallPluginFromRepo(ctx context.Context, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
53		repoURL := strings.TrimRight(opts.RepoURL, "/")
54	
55		var tags []string
56		if opts.Pin != "" {
57			tags = []string{opts.Pin}
58		} else {
59			var err error
60			tags, err = listRemoteSemverTags(ctx, repoURL)
61			if err != nil {
62				return nil, err
63			}
64			if len(tags) == 0 {
65				return nil, fmt.Errorf("%s has no semver tags; pass --pin <tag> to install a non-semver tag", repoURL)
66			}
67			if len(tags) > maxTagFallbacks {
68				tags = tags[:maxTagFallbacks]
69			}
70		}
71	
72		var lastErr error
73		for i, tag := range tags {
74			res, err := installRepoAtTag(ctx, repoURL, tag, opts)
75			if err == nil {
76				res.SkippedTags = tags[:i]
77				return res, nil
78			}
79			lastErr = err
80			if !errors.Is(err, errAssetNotFound) {
81				return nil, err
82			}
83		}
84		return nil, lastErr
85	}
86	
87	func installRepoAtTag(ctx context.Context, repoURL, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
88		meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
89		if err != nil {
90			return nil, err
91		}
92		var name string
93		if meta != nil && meta.Name != "" {
94			name = meta.Name
95		} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
96			return nil, err
97		}
98	
99		if existing, err := FindInstalledPlugin(name); err != nil {
100			return nil, err
101		} else if existing != nil && !opts.Force {
102			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
103		}
104	
105		staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
106		if err != nil {
107			return nil, fmt.Errorf("create staging dir: %w", err)
108		}
109		defer os.RemoveAll(staging)
110	
111		asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging)
112		if err != nil {
113			return nil, err
114		}
115	
116		binBase := pluginBinaryPrefix + name
117		if runtime.GOOS == windowsGOOS {
118			binBase += ".exe"
119		}
120		stagedBin := filepath.Join(staging, "extracted-"+binBase)
121		if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
122			return nil, err
123		}
124	
125		pkgDir, err := EnsurePluginPkgDir(name)
126		if err != nil {
127			return nil, err
128		}
129		sweepOldBinaries(pkgDir)
130		pkgBin := filepath.Join(pkgDir, binBase)
131		if err := replaceBinary(stagedBin, pkgBin); err != nil {
132			return nil, fmt.Errorf("place plugin binary: %w", err)
133		}
134	
135		installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
136		if err != nil {
137			return nil, err
138		}
139	
140		manifest := &PluginManifest{
141			Name:        name,
142			RepoURL:     repoURL,
143			Tag:         tag,
144			Asset:       asset.Asset,
145			SHA256:      asset.SHA256,
146			Pinned:      opts.Pin != "",
147			InstalledAt: time.Now().UTC(),
148		}
149		if meta != nil {
150			manifest.Requires = meta.Requires
151		}
152		if err := SavePluginManifest(manifest); err != nil {
153			return nil, err
154		}
155		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta}, nil
156	}
157	
158	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
159	type UpgradeOutcome struct {
160		Name string
161		// Pinned: skipped because the manifest is pinned.
162		Pinned bool
163		// UpToDate: already at the newest tag.
164		UpToDate bool
165		// FromTag/ToTag are set when an upgrade actually happened.
166		FromTag, ToTag string
167	}
168	
169	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
170	// plugin and reinstalls when it differs from the manifest's tag. Plugins
171	// without a manifest (local-dev symlinks) are not upgradable.
172	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
173		m, err := LoadPluginManifest(name)
174		if err != nil {
175			return nil, err
176		}
177		if m == nil {
178			return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
179		}
180		if m.Pinned {
181			return &UpgradeOutcome{Name: name, Pinned: true}, nil
182		}
183		tags, err := listRemoteSemverTags(ctx, m.RepoURL)
184		if err != nil {
185			return nil, err
186		}
187		if len(tags) == 0 {
188			return nil, fmt.Errorf("%s has no semver tags", m.RepoURL)
189		}
190		// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
191		// same version, and a remote that re-tagged with the other spelling
192		// must not trigger a reinstall.
193		if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
194			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
195		}
196		res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{RepoURL: m.RepoURL, Force: true})
197		if err != nil {
198			return nil, err
199		}
200		// The install may have fallen back past an asset-less newest tag and
201		// landed on the version already installed — that's up-to-date, not an
202		// upgrade line claiming X → X.
203		if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
204			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
205		}
206		return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
207	}
208	
209	// replaceBinary moves src over dest atomically. On Windows, a running
210	// executable can't be replaced (sharing violation) but it *can* be renamed:
211	// move the old binary aside to a .old-<rand> file and retry; leftovers are
212	// swept on the next install. os.Rename fails across filesystems (staging is
213	// in the system temp dir), so a copy fallback covers that case.
214	func replaceBinary(src, dest string) error {
215		err := os.Rename(src, dest)
216		if err == nil {
217			return nil
218		}
219		if runtime.GOOS == windowsGOOS {
220			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
221				if err = os.Rename(src, dest); err == nil {
222					return nil
223				}
224			}
225		}
226		// Cross-device rename: copy + fsync-free write, then remove src.
227		in, openErr := os.Open(src) //nolint:gosec // staging file we created
228		if openErr != nil {
229			return errors.Join(err, openErr)
230		}
231		defer in.Close()
232		if writeErr := writeExecutable(in, dest); writeErr != nil {
233			return errors.Join(err, writeErr)
234		}
235		_ = os.Remove(src)
236		return nil
237	}
238	
239	// oldBinaryAsidePath returns a unique .old- sibling path for the
240	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
241	func oldBinaryAsidePath(dest string) string {
242		var b [4]byte
243		if _, err := rand.Read(b[:]); err != nil {
244			return dest + ".old-fallback"
245		}
246		return dest + ".old-" + hex.EncodeToString(b[:])
247	}
248	
249	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
250	// rename-aside fallback. Failures are ignored — the files are inert.
251	func sweepOldBinaries(pkgDir string) {
252		entries, err := os.ReadDir(pkgDir)
253		if err != nil {
254			return
255		}
256		for _, e := range entries {
257			if strings.Contains(e.Name(), ".old-") {
258				_ = os.Remove(filepath.Join(pkgDir, e.Name()))
259			}
260		}
261	}
262	
263	// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
264	// The dependency guard lives in the command layer so --force can bypass it.
265	func RemoveManagedPlugin(name string) error {
266		if err := RemoveInstalledPlugin(name); err != nil {
267			return err
268		}
269		return RemovePluginPkg(name)
270	}
