1	package cli
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"log/slog"
11		"os"
12		"path/filepath"
13		"strings"
14		"time"
15	
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/internal/entireclient/userdirs"
18	)
19	
20	// Plugin discovery rides on a git-synced index, krew-style: the index is
21	// itself a git repository containing index.json, shallow-cloned into the
22	// user cache and re-pulled on a TTL. No hosted service, no forge REST API —
23	// any git server can host an index, and a repo can point contributors at an
24	// internal catalog via plugins.index_url in .entire/settings.json.
25	const (
26		// defaultPluginIndexURL is the built-in curated index.
27		defaultPluginIndexURL = "https://github.com/entireio/plugin-index"
28		// pluginIndexEnvVar overrides the index URL (forwarded to plugin
29		// children automatically via the ENTIRE_ allowlist prefix).
30		pluginIndexEnvVar = "ENTIRE_PLUGIN_INDEX_URL"
31		// pluginIndexFileName is the catalog file at the index repo root.
32		pluginIndexFileName = "index.json"
33		// pluginIndexSyncMarker records the last successful sync time as the
34		// marker file's mtime. Untracked, so fetch/reset never touches it.
35		pluginIndexSyncMarker = ".entire-last-sync"
36	)
37	
38	// PluginIndex is the parsed catalog. Decoding is deliberately lenient
39	// (unknown fields ignored) so an index that grows new fields doesn't break
40	// older CLI versions fleet-wide.
41	type PluginIndex struct {
42		Version int                `json:"version"`
43		Plugins []PluginIndexEntry `json:"plugins"`
44	}
45	
46	// PluginIndexEntry describes one plugin in the catalog.
47	type PluginIndexEntry struct {
48		Name        string `json:"name"`
49		RepoURL     string `json:"repo_url"`
50		Description string `json:"description,omitempty"`
51		Official    bool   `json:"official,omitempty"`
52		// Platforms lists supported GOOS values when the plugin doesn't ship
53		// the full matrix; empty means all.
54		Platforms []string `json:"platforms,omitempty"`
55	}
56	
57	// Find returns the entry with the given bare name, or nil.
58	func (idx *PluginIndex) Find(name string) *PluginIndexEntry {
59		if idx == nil {
60			return nil
61		}
62		for i := range idx.Plugins {
63			if idx.Plugins[i].Name == name {
64				return &idx.Plugins[i]
65			}
66		}
67		return nil
68	}
69	
70	// Search returns entries whose name or description contains term
71	// (case-insensitive). An empty term returns everything.
72	func (idx *PluginIndex) Search(term string) []PluginIndexEntry {
73		if idx == nil {
74			return nil
75		}
76		if term == "" {
77			return idx.Plugins
78		}
79		t := strings.ToLower(term)
80		var out []PluginIndexEntry
81		for _, e := range idx.Plugins {
82			if strings.Contains(strings.ToLower(e.Name), t) || strings.Contains(strings.ToLower(e.Description), t) {
83				out = append(out, e)
84			}
85		}
86		return out
87	}
88	
89	// HasRepoURL reports whether a repo URL is listed in the index — the trust
90	// check for install confirmations. Compared with the .git suffix and
91	// trailing slashes normalized.
92	func (idx *PluginIndex) HasRepoURL(repoURL string) bool {
93		if idx == nil {
94			return false
95		}
96		want := normalizeRepoURL(repoURL)
97		for _, e := range idx.Plugins {
98			if normalizeRepoURL(e.RepoURL) == want {
99				return true
100			}
101		}
102		return false
103	}
104	
105	func normalizeRepoURL(u string) string {
106		return strings.TrimSuffix(strings.TrimRight(strings.TrimSpace(u), "/"), ".git")
107	}
108	
109	// resolvePluginIndexURL applies the documented precedence: --index flag >
110	// ENTIRE_PLUGIN_INDEX_URL > settings (local over project) > built-in
111	// default. Settings load failures fall through to the default rather than
112	// blocking discovery; the failure is logged at debug.
113	func resolvePluginIndexURL(ctx context.Context, flagValue string) string {
114		if flagValue != "" {
115			return flagValue
116		}
117		if v := os.Getenv(pluginIndexEnvVar); v != "" {
118			return v
119		}
120		s, err := LoadEntireSettings(ctx)
121		if err != nil {
122			logging.Debug(ctx, "plugin index: settings load failed, using default index", slog.String("error", err.Error()))
123			return defaultPluginIndexURL
124		}
125		if u := s.PluginIndexURL(); u != "" {
126			return u
127		}
128		return defaultPluginIndexURL
129	}
130	
131	// pluginIndexTTL returns the freshness window from settings (default 24h).
132	func pluginIndexTTL(ctx context.Context) time.Duration {
133		s, err := LoadEntireSettings(ctx)
134		if err != nil {
135			return 24 * time.Hour
136		}
137		return s.PluginIndexTTL()
138	}
139	
140	// pluginIndexCacheDir is the per-URL local copy. Keyed by a hash of the
141	// URL so switching indexes (or per-repo overrides) never serves one
142	// catalog's cache for another.
143	func pluginIndexCacheDir(indexURL string) (string, error) {
144		cache := userdirs.Cache()
145		if cache == "" {
146			return "", errors.New("cannot resolve user cache directory")
147		}
148		sum := sha256.Sum256([]byte(normalizeRepoURL(indexURL)))
149		return filepath.Join(cache, "plugin-index", hex.EncodeToString(sum[:6])), nil
150	}
151	
152	// SyncPluginIndex returns the catalog for indexURL, cloning or refreshing
153	// the local copy as needed. force bypasses the TTL. When a refresh fails
154	// but a previous copy exists, the stale copy is used with a warning logged
155	// — discovery shouldn't hard-fail because a laptop is offline.
156	func SyncPluginIndex(ctx context.Context, indexURL string, force bool) (*PluginIndex, error) {
157		dir, err := pluginIndexCacheDir(indexURL)
158		if err != nil {
159			return nil, err
160		}
161		marker := filepath.Join(dir, pluginIndexSyncMarker)
162		_, statErr := os.Stat(filepath.Join(dir, ".git"))
163		cloned := statErr == nil
164	
165		fresh := false
166		if cloned && !force {
167			if info, err := os.Stat(marker); err == nil {
168				fresh = time.Since(info.ModTime()) < pluginIndexTTL(ctx)
169			}
170		}
171	
172		switch {
173		case !cloned:
174			// A previously interrupted clone can leave a partial directory
175			// without .git. git refuses to clone into a non-empty target, so
176			// without this sweep, discovery would stay wedged until the user
177			// cleared the cache by hand.
178			if err := os.RemoveAll(dir); err != nil {
179				return nil, fmt.Errorf("clear stale index cache: %w", err)
180			}
181			if err := os.MkdirAll(filepath.Dir(dir), 0o750); err != nil {
182				return nil, fmt.Errorf("create index cache dir: %w", err)
183			}
184			if _, err := gitQuiet(ctx, "clone", "--depth", "1", "--quiet", indexURL, dir).Output(); err != nil {
185				return nil, fmt.Errorf("clone plugin index %s: %w%s", indexURL, err, stderrSuffix(err))
186			}
187			touchFile(marker)
188		case !fresh:
189			if err := refreshPluginIndexClone(ctx, dir); err != nil {
190				logging.Warn(ctx, "plugin index refresh failed; using cached copy",
191					slog.String("index", indexURL), slog.String("error", err.Error()))
192			} else {
193				touchFile(marker)
194			}
195		}
196	
197		return loadPluginIndexFromDir(dir, indexURL)
198	}
199	
200	// refreshPluginIndexClone updates an existing shallow clone to the remote
201	// tip regardless of the remote's default branch name.
202	func refreshPluginIndexClone(ctx context.Context, dir string) error {
203		if _, err := gitQuiet(ctx, "-C", dir, "fetch", "--depth", "1", "--quiet", "origin", "HEAD").Output(); err != nil {
204			return fmt.Errorf("fetch: %w%s", err, stderrSuffix(err))
205		}
206		if _, err := gitQuiet(ctx, "-C", dir, "reset", "--hard", "--quiet", "FETCH_HEAD").Output(); err != nil {
207			return fmt.Errorf("reset: %w%s", err, stderrSuffix(err))
208		}
209		return nil
210	}
211	
212	func touchFile(path string) {
213		now := time.Now()
214		if err := os.Chtimes(path, now, now); err == nil {
215			return
216		}
217		if f, err := os.Create(path); err == nil { //nolint:gosec // marker file inside our cache dir
218			_ = f.Close()
219		}
220	}
221	
222	func loadPluginIndexFromDir(dir, indexURL string) (*PluginIndex, error) {
223		data, err := os.ReadFile(filepath.Join(dir, pluginIndexFileName)) //nolint:gosec // file inside our cache dir
224		if err != nil {
225			return nil, fmt.Errorf("plugin index %s has no readable %s: %w", indexURL, pluginIndexFileName, err)
226		}
227		var idx PluginIndex
228		if err := json.Unmarshal(data, &idx); err != nil {
229			return nil, fmt.Errorf("parse %s from %s: %w", pluginIndexFileName, indexURL, err)
230		}
231		if idx.Version != 1 {
232			return nil, fmt.Errorf("plugin index %s declares unsupported version %d (this CLI understands 1; upgrade entire?)", indexURL, idx.Version)
233		}
234		var valid []PluginIndexEntry
235		for _, e := range idx.Plugins {
236			if validatePluginName(e.Name) != nil || e.RepoURL == "" {
237				continue // tolerate bad entries rather than failing the catalog
238			}
239			valid = append(valid, e)
240		}
241		idx.Plugins = valid
242		return &idx, nil
243	}
