1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"os/exec"
7		"runtime"
8		"strings"
9	
10		"golang.org/x/mod/semver"
11	)
12	
13	// Dependency handling is install-time only. Dispatch stays zero-cost: a
14	// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
15	// bin dir is prepended for plugin children), and `entire plugin doctor`
16	// reports drift after the fact. There is deliberately no version-range
17	// solver — requirements carry at most a minimum version.
18	
19	// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
20	// practice; the bound turns a metadata cycle that slips past the visited
21	// set (e.g. two names aliasing one repo) into an error instead of a hang.
22	const maxDepDepth = 10
23	
24	// DepAction is one planned dependency install or upgrade.
25	type DepAction struct {
26		Name       string
27		RepoURL    string
28		MinVersion string
29		// Upgrade is true when the dependency is installed but below
30		// MinVersion; the action reinstalls at the latest tag.
31		Upgrade bool
32		// CurrentTag is the installed tag for upgrades.
33		CurrentTag string
34		// FromIndex is true when the repo URL came from the index (trusted)
35		// rather than from another plugin's metadata.
36		FromIndex bool
37	}
38	
39	// DepPlan is the result of resolving a plugin's transitive requirements.
40	type DepPlan struct {
41		Actions []DepAction
42		// Warnings are non-blocking observations, e.g. a dependency satisfied
43		// from raw $PATH whose version cannot be verified.
44		Warnings []string
45	}
46	
47	// PlanDependencyInstalls resolves the transitive requirements of rootReqs
48	// into ordered install/upgrade actions. Missing dependencies must be
49	// resolvable to a repo URL via the requirement itself or the index. The
50	// visited set plus a depth bound make cycles an error path, not a hang.
51	func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
52		plan := &DepPlan{}
53		visited := map[string]bool{}
54		if err := planDeps(ctx, rootReqs, idx, plan, visited, 0); err != nil {
55			return nil, err
56		}
57		return plan, nil
58	}
59	
60	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, visited map[string]bool, depth int) error {
61		if depth > maxDepDepth {
62			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
63		}
64		for _, req := range reqs {
65			if visited[req.Name] {
66				continue
67			}
68			visited[req.Name] = true
69	
70			satisfied, warning, err := dependencySatisfied(req)
71			if err != nil {
72				return err
73			}
74			if warning != "" {
75				plan.Warnings = append(plan.Warnings, warning)
76			}
77			if satisfied {
78				// An already-satisfied managed dependency can itself have
79				// gaps (e.g. its own dep was removed with --force since
80				// install). Walk its recorded requirements — offline, from
81				// the manifest — so installing a parent repairs the whole
82				// chain instead of stopping at the first satisfied node.
83				// PATH/local-dev installs have no manifest; doctor covers
84				// those.
85				m, err := LoadPluginManifest(req.Name)
86				if err != nil {
87					return err
88				}
89				if m != nil {
90					if err := planDeps(ctx, m.Requires, idx, plan, visited, depth+1); err != nil {
91						return err
92					}
93				}
94				continue
95			}
96	
97			m, err := LoadPluginManifest(req.Name)
98			if err != nil {
99				return err
100			}
101			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
102			if m != nil {
103				// Installed but below min_version: upgrade in place from its
104				// recorded repo.
105				action.Upgrade = true
106				action.CurrentTag = m.Tag
107				action.RepoURL = m.RepoURL
108			} else {
109				action.RepoURL = req.RepoURL
110				if action.RepoURL == "" {
111					if e := idx.Find(req.Name); e != nil {
112						action.RepoURL = e.RepoURL
113						action.FromIndex = true
114					}
115				} else if idx.HasRepoURL(action.RepoURL) {
116					action.FromIndex = true
117				}
118				if action.RepoURL == "" {
119					return fmt.Errorf("dependency %q is not installed and has no repo URL (not in the plugin index either); add repo_url to the requirement or install it manually", req.Name)
120				}
121			}
122			plan.Actions = append(plan.Actions, action)
123	
124			// Recurse into what the dependency itself requires, using metadata
125			// only — nothing is downloaded during planning. Inspection
126			// failures don't fail the plan (the install will surface hard
127			// errors itself), but they must not be silent either: a confirmed
128			// plan that quietly omitted nested dependencies would look
129			// complete while leaving gaps for doctor to find.
130			tag := ""
131			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
132				tag = tags[0]
133			}
134			if tag == "" {
135				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, action.RepoURL))
136				continue
137			}
138			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
139			if err != nil {
140				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
141				continue
142			}
143			if meta == nil {
144				continue // no metadata file: no declared dependencies
145			}
146			if err := planDeps(ctx, meta.Requires, idx, plan, visited, depth+1); err != nil {
147				return err
148			}
149		}
150		return nil
151	}
152	
153	// dependencySatisfied checks whether a requirement is already met, in
154	// order: managed install with manifest (version-checkable) → managed entry
155	// without manifest (local-dev, version unknown) → raw $PATH (version
156	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
157	// (main.go restores it for built-ins), so LookPath here sees only
158	// raw-PATH plugins — managed entries are checked explicitly first.
159	func dependencySatisfied(req PluginRequirement) (satisfied bool, warning string, err error) {
160		m, err := LoadPluginManifest(req.Name)
161		if err != nil {
162			return false, "", err
163		}
164		if m != nil {
165			if req.MinVersion == "" || semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0 {
166				return true, "", nil
167			}
168			return false, "", nil // triggers the upgrade path in planDeps
169		}
170		installed, err := FindInstalledPlugin(req.Name)
171		if err != nil {
172			return false, "", err
173		}
174		if installed != nil {
175			return true, unverifiableVersionWarning(req, "a local-dev install"), nil
176		}
177		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
178			return true, unverifiableVersionWarning(req, "$PATH"), nil
179		}
180		return false, "", nil
181	}
182	
183	func unverifiableVersionWarning(req PluginRequirement, source string) string {
184		if req.MinVersion == "" {
185			return ""
186		}
187		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
188	}
189	
190	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
191	func ExecuteDepPlan(ctx context.Context, plan *DepPlan) error {
192		for _, a := range plan.Actions {
193			if _, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{RepoURL: a.RepoURL, Force: a.Upgrade}); err != nil {
194				return fmt.Errorf("install dependency %q: %w", a.Name, err)
195			}
196		}
197		return nil
198	}
199	
200	// DependentsOf returns the names of managed plugins whose manifests list
201	// name as a requirement — the remove guard. Computed by scanning
202	// pkg/*/manifest.yml; no extra state to maintain.
203	func DependentsOf(name string) ([]string, error) {
204		manifests, err := ListPluginManifests()
205		if err != nil {
206			return nil, err
207		}
208		var out []string
209		for _, m := range manifests {
210			for _, req := range m.Requires {
211				if req.Name == name {
212					out = append(out, m.Name)
213					break
214				}
215			}
216		}
217		return out, nil
218	}
219	
220	// PluginDoctorIssue is one problem found by RunPluginDoctor.
221	type PluginDoctorIssue struct {
222		Plugin  string
223		Problem string
224		Fix     string
225	}
226	
227	// RunPluginDoctor checks every managed plugin: bin entry present, dangling
228	// local-dev symlinks, dependency presence and min_versions, and (macOS) a
229	// quarantine attribute that would block execution.
230	func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
231		var issues []PluginDoctorIssue
232	
233		installed, err := ListInstalledPlugins()
234		if err != nil {
235			return nil, err
236		}
237		installedByName := map[string]*InstalledPlugin{}
238		for _, p := range installed {
239			installedByName[p.Name] = p
240			if p.Symlink {
241				if _, err := exec.LookPath(p.Path); err != nil {
242					issues = append(issues, PluginDoctorIssue{
243						Plugin:  p.Name,
244						Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
245						Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
246					})
247				}
248			}
249			if q := quarantinedPath(ctx, p.Path); q != "" {
250				issues = append(issues, PluginDoctorIssue{
251					Plugin:  p.Name,
252					Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
253					Fix:     "run: xattr -d com.apple.quarantine " + q,
254				})
255			}
256		}
257	
258		manifests, err := ListPluginManifests()
259		if err != nil {
260			return nil, err
261		}
262		for _, m := range manifests {
263			if installedByName[m.Name] == nil {
264				issues = append(issues, PluginDoctorIssue{
265					Plugin:  m.Name,
266					Problem: "has an install manifest but no entry in the managed bin dir",
267					Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", m.RepoURL),
268				})
269			}
270			for _, req := range m.Requires {
271				satisfied, warning, err := dependencySatisfied(req)
272				if err != nil {
273					return nil, err
274				}
275				switch {
276				case satisfied && warning != "":
277					issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: warning, Fix: ""})
278				case !satisfied:
279					dep, depErr := LoadPluginManifest(req.Name)
280					if depErr != nil {
281						return nil, depErr
282					}
283					if dep != nil {
284						issues = append(issues, PluginDoctorIssue{
285							Plugin:  m.Name,
286							Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
287							Fix:     "run: entire plugin upgrade " + req.Name,
288						})
289					} else {
290						issues = append(issues, PluginDoctorIssue{
291							Plugin:  m.Name,
292							Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
293							Fix:     "run: entire plugin install " + req.Name,
294						})
295					}
296				}
297			}
298		}
299		return issues, nil
300	}
301	
302	// quarantinedPath returns the path to flag when the file (or its symlink
303	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
304	// means "not quarantined". The attribute appears when a user manually
305	// drops a browser-downloaded binary into the managed dir — CLI downloads
306	// don't set it.
307	//
308	// Checking the bin entry is sufficient even though remote installs link
309	// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
310	// symlinks by default (-s is the flag to act on the link itself), so both
311	// the probe here and the suggested `xattr -d` fix operate on the target.
312	func quarantinedPath(ctx context.Context, path string) string {
313		if runtime.GOOS != darwinGOOS {
314			return ""
315		}
316		out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
317		if err != nil || strings.TrimSpace(string(out)) == "" {
318			return ""
319		}
320		return path
321	}
