		{Name: "unlisted", RepoURL: unlistedRepo},         // author URL that is not
		{Name: "old", MinVersion: "v9.0.0"},               // upgrade from a listed repo
	}, idx)
	if err != nil {
		t.Fatalf("PlanDependencyInstalls: %v", err)
