	for _, prefix := range []string{"https://", "ssh://", "file://", "git@"} {
		if strings.HasPrefix(p.IndexURL, prefix) {
			return nil
		}
	}
	return fmt.Errorf("plugins.index_url %q must start with https://, ssh://, file://, or git@", p.IndexURL)
